∀ {X : AlgebraicGeometry.Scheme} {F : Type} [inst : Field F] {f : X ⟶ AlgebraicGeometry.Spec ↧F} {n : ℕ} {K : X.Modules}
  (self : SurfaceLib.Canonical.TopDuality F f n K) (M : X.Modules),
  SheafOfModules.IsFinitePresentation M → Function.Bijective (SurfaceLib.Canonical.tracePairing F f n self.trace M)

∀ {F L : Type} [inst : Field F] [inst_1 : Field L] [inst_2 : Algebra F L] {E : Derivation F L L} {A : Subalgebra F L}
  (self : SurfaceLib.MuFive.HomogeneousCover E A) (j : Fin self.size),
  E ↑(self.value j) = ↑(self.weight j) * ↑(self.value j)
